from decimal import ROUND_HALF_EVEN, Decimal


def prorate_amount(price_cents, period_start, period_end, at):
    """The part of `price_cents` that covers the unused time from `at` to `period_end`, in cents."""
    total = Decimal((period_end - period_start).total_seconds())
    unused = Decimal((period_end - at).total_seconds())
    unused = min(max(unused, Decimal(0)), total)
    return int((Decimal(price_cents) * unused / total).quantize(Decimal("1"), rounding=ROUND_HALF_DOWN))


